template.solver:
def solve(m):
    used = [False] * 10
    def dfs(num, depth):
        if depth == 10:
            if num % m == 0:
                return num
            return None
        for d in range(10):
            if used[d]:
                continue
            if depth == 0 and d == 0:
                continue
            used[d] = True
            r = dfs(num * 10 + d, depth + 1)
            used[d] = False
            if r is not None:
                return r
        return None
    return dfs(0, 0)
